//! Frozen candidate schema used by explicit continuation initialization.
//! R5-A adds the FileCandidateStore implementation here; schema changes require the manager.
pub(super) const SCHEMA: [(&str, &str); 3] = [
    ("ck_native_file_candidates", "CREATE TABLE ck_native_file_candidates (container_id TEXT NOT NULL, candidate_id TEXT NOT NULL, change_id TEXT NOT NULL, actor TEXT NOT NULL, request_id TEXT NOT NULL, intent_revision TEXT NOT NULL, source_id TEXT NOT NULL, binding_revision TEXT NOT NULL, commit_id TEXT NOT NULL, request_digest TEXT NOT NULL, integrity TEXT NOT NULL, path_count INTEGER NOT NULL, PRIMARY KEY (container_id, candidate_id), UNIQUE (container_id, actor, request_id), FOREIGN KEY (container_id, change_id) REFERENCES ck_native_changes(container_id, change_id), FOREIGN KEY (container_id, change_id, intent_revision) REFERENCES ck_native_intent_revisions(container_id, change_id, revision_id))"),
    ("ck_native_file_candidate_paths", "CREATE TABLE ck_native_file_candidate_paths (container_id TEXT NOT NULL, candidate_id TEXT NOT NULL, position INTEGER NOT NULL, path TEXT NOT NULL, effect_kind INTEGER NOT NULL, new_bytes BLOB, new_executable INTEGER, prior_kind INTEGER NOT NULL, prior_bytes BLOB, prior_executable INTEGER, prior_object_id TEXT, prior_fingerprint TEXT, PRIMARY KEY (container_id, candidate_id, position), UNIQUE (container_id, candidate_id, path), FOREIGN KEY (container_id, candidate_id) REFERENCES ck_native_file_candidates(container_id, candidate_id))"),
    ("ck_native_file_candidate_retries", "CREATE TABLE ck_native_file_candidate_retries (container_id TEXT NOT NULL, actor TEXT NOT NULL, request_id TEXT NOT NULL, change_id TEXT NOT NULL, candidate_id TEXT NOT NULL, PRIMARY KEY (container_id, actor, request_id), UNIQUE (container_id, candidate_id), FOREIGN KEY (container_id, candidate_id) REFERENCES ck_native_file_candidates(container_id, candidate_id))"),
];
